export const POEMAS: readonly Poema[] = [{"n":1,"titulo":"Umbral","texto":"Vine a contar lo que la máquina no firma.\nUna página abierta no es una página viva.\nEl cable sigue caliente aunque nadie llame.\nAquí no hay premio: hay una silla y una hora.\nLo que buscas no está escondido, está delante.\nSe lee dos veces: una el poema, otra el fondo.\nAprende a leer el borde y el borde te responde.\nQuien llega hasta el final ya no necesita puerta."},{"n":2,"titulo":"Inventario","texto":"Guardo diez cosas en un cajón que no cierra:\nuna llave sin puerta,\nun reloj que adelanta,\nla mitad de un mapa,\ntres fotos que no reconozco,\nun clavel seco entre las páginas,\nel ruido del módem a las tres,\ny el nombre de alguien que no fui.\nCuento diez y quedan ocho.\nLa que falta no la perdí: la dejé."},{"n":3,"titulo":"Ruido blanco","texto":"Mide en marzo lo que el ventilador no dice.\nAntes que amanezca, cuenta lo que oyes.\nRespira como respira una máquina encendida.\nEl fondo es una letra que no se dice.\nAl final asoma una marca en el centro."},{"n":4,"titulo":"La puerta que no abre","texto":"Hay una puerta en esta página\nque no gira, que no cede, que no existe.\nSu nombre está escrito con el color del fondo,\ny aun así se deja leer si pasas por encima.\nTres palabras guarda el marco, y un orden:\nel del cuento que empieza tarde.\nSi llegas a su [[umbral|/linde]], no busques llave:\nla casa está abierta por dentro."},{"n":5,"titulo":"Cinta de mantenimiento","texto":"03:12 reinicio programado.\n19:40 se cayó la luz del pasillo.\n08:05 alguien dejó un café frío.\n23:59 la cinta se corta sola.\n07:10 vuelve a empezar el día.\n15:33 nadie firmó la última línea.\n11:11 una vez bastó para saberlo."},{"n":6,"titulo":"Retrato del autor","texto":"Este retrato no es mío, aunque lo cuelguen.\n*Nadie* firma lo que la máquina copia.\n*Ojos* que no miran, marco vacío,\n*Manos* que no pintaron esta cara.\n*Bastidor* de un autor que nunca estuvo,\n*Rostro* prestado de quien mira.\n*Espejo* que devuelve lo que no hay."},{"n":7,"titulo":"Cifra","texto":"Tres veces conté los años que llevo aquí,\ny dos las veces que me fui sin irme.\nEl número no está en la suma:\nestá en el orden en que lo digo.\nSi me buscas en la dirección,\nno olvides que mi casa se llama cauce\ny que vivo en la tercera puerta."},{"n":8,"titulo":"Lo que la máquina olvidó","texto":"El sistema recuerda lo que le conviene.\nLo que olvidó no se borró: se quedó al borde,\nen ese punto final que no cierra nada.\nSi pasas el cursor por el último signo,\nverás que tiene puerta.\nLo que la máquina olvidó estaba escrito\nen el color de una palabra que nunca dijo: {{añil}}."}];
export const SECCIONES: Record<string, Seccion> = {"linde":{"titulo":"linde","texto":"El marco de la puerta guarda una palabra y un orden.\nLa palabra que abre es cobre, y no es un color: es lo que queda cuando el cable se quema.\nEl orden es 3 · 1 · 2. No sirve aquí: sirve en la décima."},"cauce-3":{"titulo":"cauce, tercera puerta","texto":"Aquí vive lo que no se dice.\nLa tercera puerta del cauce se llama junco, y crece donde el agua no llega."}};
